import { LANGUAGE_STORAGE_KEY, SUPPORTED_LOCALES } from './config.js';

export function languageBootstrapScript() {
  return `(function(){try{var key=${JSON.stringify(LANGUAGE_STORAGE_KEY)};var supported=${JSON.stringify(SUPPORTED_LOCALES)};var path=window.location.pathname||'/';var suffix=window.location.search+window.location.hash;var first=path.split('/').filter(Boolean)[0]||'';if(supported.indexOf(first)>0){document.documentElement.lang=first;return}if(first==='en'){try{window.localStorage.setItem(key,JSON.stringify({locale:'en',source:'manual'}))}catch(e){}window.location.replace((path.replace(/^\\/en(?=\\/|$)/,'')||'/')+suffix);return}var saved;try{saved=JSON.parse(window.localStorage.getItem(key)||'null')}catch(e){}var locale=saved&&supported.indexOf(saved.locale)>-1?saved.locale:'';if(!locale){var candidates=(navigator.languages&&navigator.languages.length?navigator.languages:[navigator.language||'']).map(function(value){return String(value||'').toLowerCase().split(/[-_]/)[0]});locale=candidates.find(function(value){return supported.indexOf(value)>-1})||'en';try{window.localStorage.setItem(key,JSON.stringify({locale:locale,source:'detected'}))}catch(e){}}document.documentElement.lang=locale;if(locale!=='en'){window.location.replace('/'+locale+(path==='/'?'':path)+suffix)}}catch(e){document.documentElement.lang='en'}})();`;
}
